18	// V2: Internal endpoint for Hydrogen loaders. Validates an affiliate slug belongs to
19	// a brand and returns the affiliate's full sitepage payload: gallery, content images,
20	// every link category (social + content + education + events + custom + synthesized
21	// booking), bio + about, document, newsletter, services, and booking.
22	//
23	// Every section that has a Draft/Live toggle in the dashboard is returned as an
24	// envelope `{state: "draft"|"live", data: <payload>|null}`. State is `live` only
25	// when BOTH is_enabled (data requirements met — e.g. gallery has images) AND
26	// is_active (the pro chose Live) are true; either being false drops the section
27	// to draft, even mid-session if a pro deletes the underlying data. Hydrogen reads
28	// `state` to decide whether to mount the section; `data` is always null when draft
29	// so draft content never leaks publicly even if Hydrogen has a bug. Per-row
30	// Draft/Live (links) is handled server-side: is_active=false rows are filtered out.
31	class HydrogenAffiliateController extends ApiController
32	{
33	    public function show(Request $request): JsonResponse
34	    {
35	        $validator = Validator::make($request->query(), [
36	            'shop_domain' => ['required', 'string', 'max:255'],
37	            'slug' => ['required', 'string', 'max:255'],
38	        ]);
39	
40	        if ($validator->fails()) {
41	            throw new ValidationException($validator);
42	        }
43	
44	        $validated = $validator->validated();
45	        $shopDomain = strtolower(trim($validated['shop_domain']));
46	        $slug = strtolower(trim($validated['slug']));
47	
48	        $integration = ProfessionalIntegration::query()
49	            ->where('shopify_shop_domain', $shopDomain)
50	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
51	            ->first();
52	
53	        if (! $integration) {
54	            return $this->error('Brand not found.', 404);
55	        }
56	
57	        $affiliate = Professional::query()
58	            ->where('handle_lc', $slug)
59	            ->whereNull('deleted_at')
60	            ->first();
61	
62	        if (! $affiliate || $affiliate->status !== 'active') {
63	            return $this->error('Affiliate not found.', 404);
64	        }
65	
66	        $linked = BrandPartnerLink::query()
67	            ->where('brand_professional_id', $integration->professional_id)
68	            ->where('affiliate_professional_id', $affiliate->id)
69	            ->exists();
70	
71	        if (! $linked) {
72	            return $this->error('Affiliate not found.', 404);
73	        }
74	
75	        $site = Site::where('professional_id', $affiliate->id)->first();
76	
77	        // Preload the site's section blocks once — every envelope helper reads
78	        // `is_active` off this collection instead of issuing one exists query
79	        // per section. Keyed by block_type for O(1) lookups.
80	        $sections = $site
81	            ? $site->sectionBlocks()->whereNull('deleted_at')->get()->keyBy('block_type')
82	            : collect();
83	
84	        // Booking data is needed both as its own section and for synthesizing
85	        // a link into the links list, so compute it once and pass the result
86	        // into getAffiliateLinks().
87	        $booking = $this->getAffiliateBooking($site, $sections);
88	
89	        // no-store: payload shape has evolved (e.g. links.id added in b9de807).
90	        // Prevent Oxygen/CDN from caching a stale shape across deploys.
91	        return $this->success([
92	            'affiliate_id' => (string) $affiliate->id,
93	            'name' => $affiliate->display_name,
94	            'slug' => $affiliate->handle,
95	            'gallery' => $this->getAffiliateGallery($site, $sections),
96	            // Content pool — no section-level gate in the dashboard, so no
97	            // envelope. Hydrogen merges these over brand defaults.
98	            'content_images' => $this->getAffiliateContent($site),
99	            'links' => $this->getAffiliateLinks($site, $booking),
100	            'bio' => $this->getAffiliateBio($affiliate, $sections),
101	            'document' => $this->getAffiliateDocument($site),
102	            'newsletter' => $this->getAffiliateNewsletter($sections),
103	            'services' => $this->getAffiliateServices($site, $affiliate->id, $sections),
104	            'booking' => $booking,
105	            // Shop has no content envelope (products come from Shopify), but
106	            // the block_id is needed so Hydrogen can fire click tracking when
107	            // the visitor opens the shop card. block_id is absent (not null)
108	            // when the block hasn't been created — Hydrogen guards on presence.
109	            'shop' => $this->sectionEnvelope($sections, 'shop', fn () => null),
110	        ])->header('Cache-Control', 'no-store');
111	    }
