165	    // ── Section envelope helper ──────────────────────────────────────────────
166	    //
167	    // Shape: ['state' => 'draft'|'live', 'data' => mixed|null].
168	    // Pass the pre-loaded sections collection so we don't re-query per call.
169	    // If the section row doesn't exist (edge case during rollout) we treat it
170	    // as draft, matching the dashboard's "missing = not yet published" rule.
171	
172	    /**
173	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
174	     * @return array{state: string, block_id?: string, data: mixed}
175	     */
176	    private function sectionEnvelope($sections, string $blockType, callable $buildData): array
177	    {
178	        $section = $sections->get($blockType);
179	        // Live = the section row exists, the pro chose Live (is_active),
180	        // AND requirements are currently met (is_enabled, written by the
181	        // visibility observers when underlying data changes). All three
182	        // must hold; any one being false drops the section to draft on the
183	        // public site, even if previously published.
184	        $isLive = $section !== null
185	            && (bool) $section->is_enabled
186	            && (bool) $section->is_active;
187	
188	        $envelope = [
189	            'state' => $isLive ? 'live' : 'draft',
190	            'data' => $isLive ? $buildData($section) : null,
191	        ];
192	
193	        // Omit block_id when the section row doesn't exist yet. Callers that
194	        // fire analytics events (e.g. shop click-tracking) can guard on key
195	        // presence rather than `block_id !== null`, which Hydrogen's pipeline
196	        // silently drops.
197	        if ($section !== null) {
198	            $envelope['block_id'] = (string) $section->id;
199	        }
200	
201	        return $envelope;
202	    }
