204	    // ── Gallery ──────────────────────────────────────────────────────────────
205	
206	    /**
207	     * Returns the gallery envelope. When live, `data` is an ordered array of
208	     * `{url, alt_text, caption, kind, poster, duration_ms}` rows covering both
209	     * images and videos (the dashboard unifies them in one grid). Per-row filter
210	     * keeps only ready rows so Hydrogen never sees processing placeholders.
211	     *
212	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
213	     * @return array{state: string, data: array|null}
214	     */
215	    private function getAffiliateGallery(?Site $site, $sections): array
216	    {
217	        return $this->sectionEnvelope($sections, 'gallery', function () use ($site): array {
218	            if (! $site) {
219	                return [];
220	            }
221	
222	            return SiteMedia::query()
223	                ->where('site_id', $site->id)
224	                ->where('pool', SiteMedia::POOL_GALLERY)
225	                ->where('is_active', true)
226	                ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
227	                ->with('mediaVariants')
228	                ->orderBy('sort_order')
229	                ->get()
230	                ->map(fn (SiteMedia $media) => $this->buildGalleryItem($media))
231	                ->filter(fn (?array $item) => $item !== null && $item['url'] !== '')
232	                ->values()
233	                ->all();
234	        });
235	    }
236	
237	    /**
238	     * Project a SiteMedia row to the Hydrogen gallery shape. Videos prefer the
239	     * HLS stream URL (plays natively in Safari + hls.js elsewhere) and fall
240	     * back to progressive MP4 variants; images use the optimised WebP.
241	     *
242	     * @return array{url: string, alt_text: string|null, caption: string|null, kind: string, poster: string|null, duration_ms: int|null}|null
243	     */
244	    private function buildGalleryItem(SiteMedia $media): ?array
245	    {
246	        $isVideo = $media->media_type === SiteMedia::MEDIA_TYPE_VIDEO;
247	
248	        if ($isVideo) {
249	            $streams = [];
250	            $variants = [];
251	            $poster = null;
252	            foreach ($media->mediaVariants as $mv) {
253	                if ($mv->artifact_type === 'hls_playlist') {
254	                    $streams[$mv->variant_key] = $mv->url;
255	                } elseif ($mv->artifact_type === 'mp4') {
256	                    $variants[$mv->variant_key] = $mv->url;
257	                } elseif ($mv->artifact_type === 'poster') {
258	                    $poster = $mv->url;
259	                }
260	            }
261	            // Prefer HLS; fall back through progressive MP4 variants to any
262	            // remaining URL. Mirrors Sidest-Hydrogen's pickVideoSrc() order.
263	            $url = $streams['optimized']
264	                ?? $streams['maximized']
265	                ?? $variants['optimized']
266	                ?? $variants['maximized']
267	                ?? $variants['original']
268	                ?? '';
269	
270	            return [
271	                'url' => $url,
272	                'alt_text' => $media->alt_text,
273	                'caption' => $media->caption,
274	                'kind' => 'video',
275	                'poster' => $poster,
276	                'duration_ms' => $media->duration_ms,
277	            ];
278	        }
279	
280	        $variantUrls = $media->variantUrls();
281	        $url = $variantUrls['optimized'] ?? $variantUrls['original'] ?? '';
282	
283	        return [
284	            'url' => $url,
285	            'alt_text' => $media->alt_text,
286	            'caption' => $media->caption,
287	            'kind' => 'image',
288	            'poster' => null,
289	            'duration_ms' => null,
290	        ];
291	    }
