295	    private function getAffiliateContent(?Site $site): array
296	    {
297	        if (! $site) {
298	            return [];
299	        }
300	
301	        return SiteMedia::query()
302	            ->where('site_id', $site->id)
303	            ->where('pool', SiteMedia::POOL_CONTENT)
304	            ->where('is_active', true)
305	            ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
306	            ->with('mediaVariants')
307	            ->orderBy('sort_order')
308	            ->get()
309	            ->map(fn (SiteMedia $media) => [
310	                'url' => $media->variantUrls()['optimized'] ?? null,
311	                'alt_text' => $media->alt_text,
312	            ])
313	            ->filter(fn (array $item) => $item['url'] !== null)
314	            ->values()
315	            ->all();
