318	    // ── Links (all categories + synthesized booking) ─────────────────────────
319	
320	    /**
321	     * Returns every live link block the affiliate has, across every category
322	     * (social, content, education, events, custom). Each link is tagged with
323	     * `category` and, for platform-tagged rows, `platform`. Booking is not a
324	     * link block on the dashboard side, but Hydrogen wants to render it
325	     * alongside the other links — when the booking section is live, we
326	     * synthesize a `{category: 'booking'}` row at the end of the list.
327	     *
328	     * @param  array{state: string, data: array|null}  $bookingEnvelope
329	     */
330	    private function getAffiliateLinks(?Site $site, array $bookingEnvelope): array
331	    {
332	        if (! $site) {
333	            return [];
334	        }
335	
336	        $rows = Block::query()
337	            ->where('site_id', $site->id)
338	            ->where('block_group', 'links')
339	            ->where('is_active', true)
340	            ->whereNull('deleted_at')
341	            ->orderBy('sort_order')
342	            ->get()
343	            ->map(function (Block $block): array {
344	                $settings = is_array($block->settings) ? $block->settings : [];
345	                $platform = is_string($settings['platform'] ?? null)
346	                    ? strtolower(trim((string) $settings['platform']))
347	                    : null;
348	                $platform = $platform !== '' ? $platform : null;
349	                // Category lives in settings to avoid a schema change for
350	                // what is effectively a free-form tag. Default to 'custom'
351	                // for older rows that pre-date the category field.
352	                $category = is_string($settings['category'] ?? null)
353	                    ? strtolower(trim((string) $settings['category']))
354	                    : 'custom';
355	
356	                $title = is_string($block->title) ? trim($block->title) : '';
357	                $url = is_string($block->url) ? trim($block->url) : '';
358	
359	                // Resilience: older link rows can have empty title/url at rest
360	                // — settings.platform + settings.handle are the source of truth
361	                // there. Rebuild both from the platform config so the row still
362	                // renders on Hydrogen without requiring a backfill migration.
363	                if (($title === '' || $url === '') && $platform !== null) {
364	                    $config = config("partna.social_platforms.{$platform}");
365	                    $handle = is_string($settings['handle'] ?? null)
366	                        ? trim((string) $settings['handle'])
367	                        : '';
368	                    if (is_array($config)) {
369	                        if ($title === '' && is_string($config['display_name'] ?? null)) {
370	                            $title = (string) $config['display_name'];
371	                        }
372	                        if ($url === '' && $handle !== '' && is_string($config['url_template'] ?? null)) {
373	                            $url = str_replace('{handle}', $handle, (string) $config['url_template']);
374	                        }
375	                    }
376	                }
377	
378	                return [
379	                    'id' => (string) $block->id,
380	                    'title' => $title,
381	                    'url' => $url,
382	                    'category' => $category !== '' ? $category : 'custom',
383	                    'platform' => $platform,
384	                ];
385	            })
386	            ->filter(fn (array $item) => $item['title'] !== '' && $item['url'] !== '')
387	            ->values()
388	            ->all();
389	
390	        // Append the synthesized booking link when booking is live + resolved.
391	        // Keeping this controller-side means themes have a single list to
392	        // render rather than special-casing booking everywhere.
393	        if ($bookingEnvelope['state'] === 'live' && is_array($bookingEnvelope['data'])) {
394	            $rows[] = [
395	                'title' => (string) ($bookingEnvelope['data']['title'] ?? 'Book now'),
396	                'url' => (string) ($bookingEnvelope['data']['resolved_url'] ?? ''),
397	                'category' => 'booking',
398	                'platform' => is_string($bookingEnvelope['data']['platform'] ?? null)
399	                    ? $bookingEnvelope['data']['platform']
400	                    : null,
401	            ];
402	            // Filter out the booking link if its url ended up empty.
403	            $rows = array_values(array_filter(
404	                $rows,
405	                fn (array $item) => $item['url'] !== '',
406	            ));
407	        }
408	
409	        return $rows;
410	    }
