412	    // ── Bio + credentials + experience ───────────────────────────────────────
413	
414	    /**
415	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
416	     * @return array{state: string, data: array|null}
417	     */
418	    private function getAffiliateBio(Professional $affiliate, $sections): array
419	    {
420	        return $this->sectionEnvelope($sections, 'bio', function () use ($affiliate): array {
421	            $about = is_array($affiliate->about) ? $affiliate->about : [];
422	            $credentials = is_array($about['credentials'] ?? null) ? $about['credentials'] : [];
423	            $experience = is_array($about['experience'] ?? null) ? $about['experience'] : [];
424	
425	            return [
426	                'text' => (string) ($affiliate->bio ?? ''),
427	                'credentials' => array_values(array_filter(array_map(
428	                    fn ($row) => $this->normaliseCredential($row),
429	                    $credentials,
430	                ))),
431	                'experience' => array_values(array_filter(array_map(
432	                    fn ($row) => $this->normaliseExperience($row),
433	                    $experience,
434	                ))),
435	            ];
436	        });
437	    }
438	
439	    /**
440	     * Normalise a credential row from the about JSONB column. The dashboard
441	     * sometimes stamps client-side UUIDs; we strip them so the wire shape is
442	     * stable for Hydrogen.
443	     */
444	    private function normaliseCredential($row): ?array
445	    {
446	        if (! is_array($row)) {
447	            return null;
448	        }
449	        $title = trim((string) ($row['title'] ?? ''));
450	        if ($title === '') {
451	            return null;
452	        }
453	
454	        return [
455	            'title' => $title,
456	            'issuer' => trim((string) ($row['issuer'] ?? '')),
457	            'year' => isset($row['year']) && $row['year'] !== '' ? (string) $row['year'] : null,
458	        ];
459	    }
460	
461	    /**
462	     * Dashboard writes experience as {role, place, start, end, description}.
463	     * Project to the Hydrogen contract {title, organisation, period} so the
464	     * wire shape mirrors credentials and the theme layer doesn't have to know
465	     * about the source schema differences.
466	     */
467	    private function normaliseExperience($row): ?array
468	    {
469	        if (! is_array($row)) {
470	            return null;
471	        }
472	
473	        // Accept both the current dashboard schema (role/place) and the older
474	        // Hydrogen contract names (title/organisation) so pre-migration rows
475	        // don't silently drop.
476	        $title = trim((string) ($row['role'] ?? $row['title'] ?? ''));
477	        if ($title === '') {
478	            return null;
479	        }
480	
481	        $organisation = trim((string) (
482	            $row['place']
483	            ?? $row['organisation']
484	            ?? $row['organization']
485	            ?? ''
486	        ));
487	
488	        $start = isset($row['start']) && $row['start'] !== '' ? (string) $row['start'] : null;
489	        // A null `end` means "currently active" per the dashboard's
490	        // ExperienceEditorModal contract — render as "Current" so the public
491	        // site reads like a CV, not a blank field.
492	        $rawEnd = $row['end'] ?? null;
493	        $end = is_string($rawEnd) && $rawEnd !== '' ? $rawEnd : null;
494	
495	        if ($start !== null) {
496	            $period = $start.' – '.($end ?? 'Current');
497	        } elseif (isset($row['period']) && $row['period'] !== '') {
498	            $period = (string) $row['period'];
499	        } else {
500	            $period = null;
501	        }
502	
503	        return [
504	            'title' => $title,
505	            'organisation' => $organisation,
506	            'period' => $period,
507	        ];
508	    }
509	
510	    // ── Document ─────────────────────────────────────────────────────────────
511	
512	    /**
513	     * Document is gated per-row (SiteMedia.is_active), not at the section
514	     * level — the dashboard's Draft/Live toggle writes is_enabled which maps
515	     * directly to SiteMedia.is_active, and there is no separate "documents"
516	     * section block that also needs flipping. If a ready + active row exists
517	     * the envelope is 'live', otherwise 'draft'.
518	     *
519	     * @return array{state: string, data: array|null}
520	     */
521	    private function getAffiliateDocument(?Site $site): array
522	    {
523	        $media = $site
524	            ? SiteMedia::query()
525	                ->where('site_id', $site->id)
526	                ->where('pool', SiteMedia::POOL_DOCUMENTS)
527	                ->where('is_active', true)
528	                ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
529	                ->orderByDesc('created_at')
530	                ->first()
531	            : null;
532	
533	        if (! $media) {
534	            return ['state' => 'draft', 'data' => null];
535	        }
536	
537	        return [
538	            'state' => 'live',
539	            'data' => [
540	                // Raw id — Hydrogen uses it to build a same-origin proxy URL
541	                // (e.g. /api/document/{id}) so react-pdf can fetch bytes
542	                // without tripping CORS. The absolute download_url below is
543	                // still used by the Download button, which triggers a
544	                // browser navigation and is not subject to CORS.
545	                'id' => (string) $media->id,
546	                'title' => $media->alt_text,
547	                'caption' => $media->caption,
548	                // Absolute URL to the backend download redirect (signed R2
549	                // URL issued server-side) so the Hydrogen payload never
550	                // carries R2 credentials.
551	                'download_url' => url('/api/public/documents/'.$media->id.'/download'),
552	                'mime' => $media->original_mime,
553	                'size_bytes' => $media->original_size_bytes,
554	            ],
555	        ];
556	    }
