590	    /**
591	     * Builds the services payload shared by the envelope and the standalone
592	     * /affiliate-services endpoint. Keeping them in one place means the two
593	     * consumers can never drift.
594	     */
595	    private function buildServicesData(?Site $site, string $affiliateId): array
596	    {
597	        $settings = is_array($site?->settings) ? $site->settings : [];
598	        $bookingMode = strtolower((string) ($settings['booking_mode'] ?? 'manual'));
599	        $manualBookingUrl = trim((string) ($settings['manual_booking_url'] ?? ''));
600	
601	        $services = Service::query()
602	            ->with('category:id,title')
603	            ->where('professional_id', $affiliateId)
604	            ->where('is_active', true)
605	            ->whereNull('deleted_at')
606	            ->orderBy('sort_order')
607	            ->orderBy('created_at')
608	            ->get()
609	            ->map(fn (Service $service): array => [
610	                'id' => $service->id,
611	                'title' => $service->title,
612	                'description' => $service->description,
613	                'price_cents' => $service->price_cents,
614	                'currency_code' => $service->currency_code,
615	                'duration_minutes' => $service->duration_minutes,
616	                'category' => $service->category?->title ?? 'Services',
617	            ])
618	            ->values()
619	            ->all();
620	
621	        return [
622	            'booking_mode' => $bookingMode,
623	            'manual_booking_url' => $manualBookingUrl !== '' ? $manualBookingUrl : null,
624	            'services' => $services,
625	        ];
626	    }
627	
628	    // ── Booking ──────────────────────────────────────────────────────────────
629	
630	    /**
631	     * Booking data lives on the `booking` section block's settings — the
632	     * section-level toggle is the single gate (no separate booking section
633	     * visibility state to reconcile). When live + a booking URL is set,
634	     * returns the resolved URL; otherwise data is null.
635	     *
636	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
637	     * @return array{state: string, data: array|null}
638	     */
639	    private function getAffiliateBooking(?Site $site, $sections): array
640	    {
641	        return $this->sectionEnvelope($sections, 'booking', function (Block $section): ?array {
642	            $settings = is_array($section->settings) ? $section->settings : [];
643	            $bookingUrl = trim((string) ($settings['booking_url'] ?? ''));
644	
645	            // Platform is stored next to booking_url when known (calendly, acuity,
646	            // etc.) so themes can pick a wordmark; missing platform = generic "book now" CTA.
647	            $platform = is_string($settings['platform'] ?? null)
648	                ? strtolower(trim((string) $settings['platform']))
649	                : null;
650	
651	            // Title override — affiliate may want "Book a consult" instead of "Book now".
652	            $title = is_string($settings['title'] ?? null)
653	                ? trim((string) $settings['title'])
654	                : '';
655	
656	            if ($bookingUrl === '') {
657	                return null;
658	            }
659	
660	            return [
661	                'platform' => $platform !== '' ? $platform : null,
662	                'path' => $bookingUrl,
663	                // Backend currently stores the fully-resolved URL in settings.booking_url
664	                // (the dashboard normalises before save). If/when we switch to storing
665	                // platform+handle separately, resolve here.
666	                'resolved_url' => $bookingUrl,
667	                'title' => $title !== '' ? $title : 'Book now',
668	            ];
669	        });
670	    }
671	}
